insert into public.products (slug, category, kind, collection, name, blurb, defaults, sort) values
  ('wave-switch', 'cover', 'cover', 'waves', '{"en":"Wave switch cover","hy":"Ալիք անջատիչի համար"}'::jsonb, '{"en":"A slow wave across a single switch. Calm, but never plain.","hy":"Դանդաղ ալիք մեկ անջատիչի վրա։ Հանգիստ, բայց ոչ ձանձրալի։"}'::jsonb, '{"sections":1,"slots":["k1"],"shape":"oval","orientation":"h","pattern":"waves","combo":"peach-sky"}'::jsonb, '0'),
  ('cookie-duo', 'cover', 'cover', 'soft', '{"en":"Cookie double cover","hy":"Կրկնակի «Թխվածքաբլիթ»"}'::jsonb, '{"en":"Two keys, soft scalloped edges and a floating shape in your colors.","hy":"Երկու ստեղն, փափուկ ալիքավոր եզրեր և լողացող ձև քո գույներով։"}'::jsonb, '{"sections":2,"slots":["k1","k1"],"shape":"cookie","orientation":"h","pattern":"blobs","combo":"berry-milk"}'::jsonb, '1'),
  ('dotty-socket', 'cover', 'cover', 'graphic', '{"en":"Dotty socket cover","hy":"Կետավոր վարդակ"}'::jsonb, '{"en":"Polka dots around the socket you use every day.","hy":"Կետեր այն վարդակի շուրջ, որից օգտվում ես ամեն օր։"}'::jsonb, '{"sections":1,"slots":["socket"],"shape":"square","orientation":"h","pattern":"dots","combo":"butter-mint"}'::jsonb, '2'),
  ('cracker-trio', 'cover', 'cover', 'graphic', '{"en":"Cracker trio","hy":"«Կրեկեր» եռյակ"}'::jsonb, '{"en":"A switch and two sockets in one checked frame, with crisp cracker edges.","hy":"Անջատիչ և երկու վարդակ մեկ վանդակավոր շրջանակում՝ կրեկերի եզրերով։"}'::jsonb, '{"sections":3,"slots":["k2","socket","socket"],"shape":"cracker","orientation":"h","pattern":"checks","combo":"sunset"}'::jsonb, '3'),
  ('plum-cartouche', 'cover', 'cover', 'everyday', '{"en":"Plum cartouche","hy":"Սալորագույն քարտուշ"}'::jsonb, '{"en":"A framed, slightly theatrical shape for a double switch.","hy":"Շրջանակված, մի փոքր թատերական ձև կրկնակի անջատիչի համար։"}'::jsonb, '{"sections":1,"slots":["k2"],"shape":"cartouche","orientation":"h","pattern":"plain","combo":"night-plum"}'::jsonb, '4'),
  ('stripe-tower', 'cover', 'cover', 'everyday', '{"en":"Stripe tower","hy":"Գծավոր աշտարակ"}'::jsonb, '{"en":"Four stacked sections for the busy wall by the kitchen counter.","hy":"Չորս հարկանի բլոկ խոհանոցի զբաղված պատի համար։"}'::jsonb, '{"sections":4,"slots":["k1","k1","socket","socket"],"shape":"square","orientation":"v","pattern":"stripes","combo":"classic"}'::jsonb, '5'),
  ('cloud-cookie', 'cover', 'cover', 'soft', '{"en":"Cookie switch cover","hy":"«Թխվածքաբլիթ» անջատիչ"}'::jsonb, '{"en":"One key, soft scallops, one quiet color.","hy":"Մեկ ստեղն, փափուկ եզրեր, մեկ հանգիստ գույն։"}'::jsonb, '{"sections":1,"slots":["k1"],"shape":"cookie","orientation":"h","pattern":"plain","combo":"berry-milk"}'::jsonb, '6'),
  ('sunny-sockets', 'cover', 'cover', 'waves', '{"en":"Sunny double socket","hy":"Արևոտ կրկնակի վարդակ"}'::jsonb, '{"en":"Two sockets wrapped in warm, rolling waves.","hy":"Երկու վարդակ՝ տաք, գլորվող ալիքների մեջ։"}'::jsonb, '{"sections":2,"slots":["socket","socket"],"shape":"oval","orientation":"h","pattern":"waves","combo":"sunset"}'::jsonb, '7'),
  ('bean-tray', 'decor', 'tray', 'objects', '{"en":"Bean tray","hy":"«Լոբի» սկուտեղ"}'::jsonb, '{"en":"A soft tray that catches keys, rings and the small things by the door.","hy":"Փափուկ սկուտեղ բանալիների, մատանիների և դռան մոտի մանրուքների համար։"}'::jsonb, '{"shape":"bean","size":"m","pattern":"plain","combo":"sunset"}'::jsonb, '8'),
  ('cloud-tray', 'decor', 'tray', 'objects', '{"en":"Cloud tray","hy":"«Ամպ» սկուտեղ"}'::jsonb, '{"en":"A cloud-shaped dish for a bedside table.","hy":"Ամպաձև աման մահճակալի կողքի սեղանի համար։"}'::jsonb, '{"shape":"cloud","size":"s","pattern":"dots","combo":"peach-sky"}'::jsonb, '9'),
  ('wavy-frame', 'decor', 'frame', 'objects', '{"en":"Wavy photo frame","hy":"Ալիքաձև լուսանկարի շրջանակ"}'::jsonb, '{"en":"A wobbly frame for the photo you actually look at.","hy":"Ալիքավոր շրջանակ այն լուսանկարի համար, որին իսկապես նայում ես։"}'::jsonb, '{"shape":"wavy","size":"s","pattern":"plain","combo":"berry-milk"}'::jsonb, '10'),
  ('puddle-mirror', 'decor', 'mirror', 'objects', '{"en":"Puddle mirror","hy":"«Ջրափոս» հայելի"}'::jsonb, '{"en":"A soft-edged wall mirror with a colored rim.","hy":"Փափուկ եզրերով պատի հայելի՝ գունավոր եզրագծով։"}'::jsonb, '{"shape":"blob","size":"m","pattern":"plain","combo":"peach-sky"}'::jsonb, '11')
